1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block: a request is a hard duplicate when an existing active owner shares both the
11	 * new owner's {@link HouseholdNormalizer#id(String, String) household id} (same last name and
12	 * postcode) and its telephone, and is rejected with a 409 via {@link DuplicateIdentityException}. A
13	 * household member giving a <em>different</em> telephone is not a hard duplicate: it passes this
14	 * block and is instead marked for follow-up by {@link FlagPossibleDuplicate} and held to its
15	 * household level ceiling by {@link CapMembershipLevel}. Setting {@code sharesHousehold} acknowledges
16	 * the shared household and bypasses this block outright, so the new owner is created as a declared
17	 * household member. Runs after {@link AssignHousehold}, so the built owner already carries its
18	 * household id. Soft-deleted owners are ignored, so a match that has since been deleted no longer
19	 * blocks the create.
20	 */
21	public class EnsureUniqueIdentity {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	        String householdId = owner.getHouseholdId();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.isActive() && HouseholdNormalizer.belongsTo(existing, householdId)
31	                    && owner.getTelephone().equals(existing.getTelephone())) {
32	                throw new DuplicateIdentityException(householdId);
33	            }
34	        }
35	    }
36	}
