1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft duplicate: a new owner that passed the duplicate block (see
10	 * {@link EnsureUniqueIdentity}) but still shares an existing owner's
11	 * {@link HouseholdNormalizer#id(String, String) household id} (same last name and postcode) while
12	 * giving a different telephone. Such a request is allowed but marked for follow-up: the built
13	 * {@link Owner} records {@code possibleDuplicate} true and {@code possibleDuplicateOf} the matching
14	 * owner's id (the earliest match when several exist). A <em>declared</em> household member (the
15	 * request set {@code sharesHousehold}) is never flagged — deliberately sharing a household is not a
16	 * suspected duplicate. When nothing matches, {@code possibleDuplicate} is false and
17	 * {@code possibleDuplicateOf} stays absent. Runs before {@link SaveOwner}, so the new owner is not
18	 * yet persisted and is never matched against itself. Soft-deleted owners are ignored, mirroring the
19	 * duplicate block in {@link EnsureUniqueIdentity}. Mutates the built {@link Owner} in place.
20	 */
21	public class FlagPossibleDuplicate {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
24	        owner.setPossibleDuplicate(false);
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	        String householdId = owner.getHouseholdId();
29	        Owner match = null;
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isActive() && HouseholdNormalizer.belongsTo(existing, householdId)
32	                    && !owner.getTelephone().equals(existing.getTelephone())) {
33	                if (match == null || existing.getId() < match.getId()) {
34	                    match = existing;
35	                }
36	            }
37	        }
38	        if (match != null) {
39	            owner.setPossibleDuplicate(true);
40	            owner.setPossibleDuplicateOf(match.getId());
41	        }
42	    }
43	}
