1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Stamps the built owner with its deterministic {@link HouseholdNormalizer#id(String, String)
8	 * household id}, derived purely from the owner's last name and postcode. Because the id is a function
9	 * of those two fields alone, owners with the same last name and postcode share it automatically —
10	 * there is no scan of existing owners and no dependence on {@code sharesHousehold}. Runs after
11	 * {@link BuildOwner} and mutates the built {@link Owner} in place; the stamped id then drives the
12	 * duplicate block ({@link EnsureUniqueIdentity}), the household-size count ({@link CountHousehold})
13	 * and the possible-duplicate flag ({@link FlagPossibleDuplicate}).
14	 */
15	public class AssignHousehold {
16	
17	    public void service(@Val Owner owner) {
18	        owner.setHouseholdId(HouseholdNormalizer.id(owner.getLastName(), owner.getPostcode()));
19	    }
20	}
