1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners the new owner's household will hold once this create completes — the new
9	 * owner plus every existing owner sharing the same {@link HouseholdNormalizer#id(String, String)
10	 * household id} (same last name and postcode). Runs before {@link SaveOwner}, so the new owner is not
11	 * yet persisted and is counted explicitly. Mutates the built {@link Owner} in place.
12	 */
13	public class CountHousehold {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String householdId = owner.getHouseholdId();
17	        int members = 1;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (HouseholdNormalizer.belongsTo(existing, householdId)) {
20	                members++;
21	            }
22	        }
23	        owner.setHouseholdSize(members);
24	    }
25	}
