1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Shared SHA-256 hex helper. A pure function of its input with no dependency on other owners, used
9	 * wherever the application needs a stable, opaque token derived from a value (the region-and-hash
10	 * customerCode in {@link CustomerCode}, the household id in
11	 * {@link org.springframework.samples.petclinic.rest.function.owner.HouseholdNormalizer}).
12	 */
13	public final class Sha256 {
14	
15	    private Sha256() {
16	    }
17	
18	    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
19	    public static String hex(String value) {
20	        try {
21	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
22	            StringBuilder hex = new StringBuilder(digest.length * 2);
23	            for (byte b : digest) {
24	                hex.append(String.format("%02x", b));
25	            }
26	            return hex.toString();
27	        }
28	        catch (NoSuchAlgorithmException e) {
29	            throw new IllegalStateException("SHA-256 not available", e);
30	        }
31	    }
32	
33	    /** The first {@code length} upper-case hex characters of the SHA-256 of {@code value}. */
34	    public static String prefix(String value, int length) {
35	        return hex(value).substring(0, length).toUpperCase();
36	    }
37	}
