1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Set;
4	
5	/**
6	 * Pinned blocklist of disposable email domains. An owner whose email is registered under one of these
7	 * throwaway providers is rejected, since such an address cannot be relied on for contact. Pure lookup
8	 * with no dependency on other owners, so it is applied at request time.
9	 */
10	public final class DisposableEmailDomains {
11	
12	    /** Known disposable-mail providers, held lower-cased for case-insensitive matching. */
13	    private static final Set<String> BLOCKED = Set.of(
14	            "mailinator.com",
15	            "tempmail.com",
16	            "guerrillamail.com");
17	
18	    private DisposableEmailDomains() {
19	    }
20	
21	    /** Whether {@code domain} is a blocked disposable-mail provider (case-insensitive). */
22	    public static boolean isBlocked(String domain) {
23	        return domain != null && BLOCKED.contains(domain.toLowerCase());
24	    }
25	}
