1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	/**
6	 * Canonical email handling shared by the create pipeline: {@link NormalizeEmail} lower-cases the
7	 * stored form and validates syntax through it, and {@link IdentityKey} uses it for the email part of
8	 * the duplicate key. Not a pipeline step, so it is free to expose plain helpers.
9	 */
10	public final class EmailNormalizer {
11	
12	    /** A syntactically valid address: a local part, an {@code @}, then a dotted domain. */
13	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
14	
15	    private EmailNormalizer() {
16	    }
17	
18	    /** Whether {@code email} is a syntactically valid address. */
19	    public static boolean isValid(String email) {
20	        return email != null && EMAIL.matcher(email).matches();
21	    }
22	
23	    /** The stored form: trimmed and lower-cased. */
24	    public static String normalize(String email) {
25	        return email.trim().toLowerCase();
26	    }
27	
28	    /** The domain part (after the {@code @}) of {@code email}, or {@code null} when it has none. */
29	    public static String domainOf(String email) {
30	        if (email == null) {
31	            return null;
32	        }
33	        int at = email.lastIndexOf('@');
34	        return at < 0 ? null : email.substring(at + 1);
35	    }
36	}
