1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create request is a hard duplicate: an existing owner already shares both the new
5	 * owner's household id (same last name and postcode) and its telephone, and the request did not set
6	 * {@code sharesHousehold}. Carries the offending household id so
7	 * {@link DuplicateIdentityExceptionHandler} can report it. Handled as a 409.
8	 */
9	public class DuplicateIdentityException extends Exception {
10	
11	    private final String householdId;
12	
13	    public DuplicateIdentityException(String householdId) {
14	        super("Another owner already shares this household: " + householdId);
15	        this.householdId = householdId;
16	    }
17	
18	    public String getHouseholdId() {
19	        return householdId;
20	    }
21	}
