8	public class DuplicateIdentityExceptionHandler {
9	
10	    public void handle(@Parameter DuplicateIdentityException ex,
11	            ObjectResponse<ResponseEntity<String>> response) {
12	        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
13	    }
14	}
