1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
6	import org.springframework.samples.petclinic.util.DisposableEmailDomains;
7	
8	/**
9	 * Rejects a create request whose email is registered under a disposable-mail provider (see
10	 * {@link DisposableEmailDomains}). Runs after {@link NormalizeEmail}, so it judges the trimmed,
11	 * lower-cased form and can trust the address is syntactically valid. A missing or blank email is
12	 * allowed, keeping email optional. A blocked domain is a 400 via {@link DisposableEmailDomainException}.
13	 */
14	public class ValidateEmailDomain {
15	
16	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
17	        String email = request.getEmail();
18	        if (email == null || email.isBlank()) {
19	            return;
20	        }
21	        String domain = EmailNormalizer.domainOf(email);
22	        if (DisposableEmailDomains.isBlocked(domain)) {
23	            throw new DisposableEmailDomainException(domain);
24	        }
25	    }
26	}
