1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the telephone of a create request to canonical E.164 form (see
9	 * {@link TelephoneNormalizer#toE164(String)}). The normalized value is written back onto the
10	 * (republished) request so {@link BuildOwner} stores and later responses return the E.164 form. A
11	 * value that cannot form a valid E.164 number is rejected as a 400 via
12	 * {@link InvalidTelephoneException}.
13	 */
14	public class NormalizeTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
17	        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
18	        if (e164 == null) {
19	            throw new InvalidTelephoneException(request.getTelephone());
20	        }
21	        request.setTelephone(e164);
22	    }
23	}
