5	/**
6	 * Pinned region-to-postcode-range reference table. Each canonical region (see {@link CityRegion})
7	 * permits an inclusive 4-digit postcode range; a region not in the table — including
8	 * {@link CityRegion#UNKNOWN} — accepts any 4-digit postcode (the permissive default). Pure lookup
9	 * with no dependency on other owners.
10	 */
11	public final class RegionPostcodes {
12	
13	    /** Region -> inclusive {low, high} 4-digit postcode range. */
14	    private static final Map<String, int[]> REGION_RANGES = Map.of(
15	            "NSW", new int[] {2000, 2099},
16	            "VIC", new int[] {3000, 3099},
17	            "QLD", new int[] {4000, 4099});
18	
19	    private RegionPostcodes() {
20	    }
21	
22	    /**
23	     * Whether {@code postcode} is allowed for {@code region}: within the region's inclusive range, or
24	     * always allowed when the region has no known range.
25	     */
26	    public static boolean allows(String region, int postcode) {
27	        int[] range = REGION_RANGES.get(region);
28	        return range == null || (postcode >= range[0] && postcode <= range[1]);
29	    }
30	
31	    /**
32	     * The canonical region whose inclusive range contains {@code postcode}, or {@code null} when no
33	     * known range does. The reverse of {@link #allows(String, int)}.
34	     */
35	    public static String regionOf(int postcode) {
36	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
37	            int[] range = entry.getValue();
38	            if (postcode >= range[0] && postcode <= range[1]) {
39	                return entry.getKey();
40	            }
41	        }
42	        return null;
43	    }
44	}
